-- Descriptions, insights and founded dates for the original 3 demo startups
update public.listings set founded_on = '2024-03-01', description = coalesce(description, 'LedgerLoop creates GST-compliant invoices for freelancers and small agencies, sends them over WhatsApp and email, and follows up automatically until the client pays. Customers are designers, developers and consultants who bill Indian and overseas clients. Most revenue is on monthly plans, with a few yearly subscribers. The founder wants to move on to a larger product and is looking for an operator who can grow distribution.'),
 insights = '{"value_proposition":"GST invoices that chase themselves: create, send on WhatsApp, and get paid without awkward follow-ups.","problem":"Freelancers lose hours every month making GST invoices by hand and chasing clients who pay late.","audience":"Freelancers, design and dev agencies, independent consultants","customer_type":"B2B","pricing":"Solo ₹999/month, Studio ₹2,499/month, yearly plans at 10 months'' price","tech_stack":"Next.js, Supabase, Razorpay, WhatsApp Cloud API","acquisition_channels":"Google search for GST invoice templates, freelancer communities, CA referrals","extra":"Solo founder. Sale includes code, domain, WhatsApp templates and the customer list."}'::jsonb
 where id = '22222222-2222-4222-8222-000000000001';
update public.listings set founded_on = '2025-01-01', description = coalesce(description, 'ReelCraft AI cuts long videos, podcasts and webinars into short vertical clips with Hindi and English captions, ready for Instagram and YouTube Shorts. Customers are creators, coaching businesses and small media teams. September revenue includes a one-time lifetime-deal campaign on top of regular subscriptions, which is why that month stands out.'),
 insights = '{"value_proposition":"Upload one long video, get ten captioned reels in Hindi and English.","problem":"Creators and coaches spend hours clipping and captioning long videos for Reels and Shorts.","audience":"Creators, coaching businesses, small media teams","customer_type":"B2B and B2C","pricing":"Creator ₹999/month, Studio ₹2,499/month; a one-time lifetime deal ran in September","tech_stack":"Python, FFmpeg, Whisper, React, Razorpay","acquisition_channels":"Instagram, YouTube tutorials, a lifetime-deal campaign"}'::jsonb
 where id = '22222222-2222-4222-8222-000000000002';
update public.listings set founded_on = '2024-08-01', description = coalesce(description, 'ShopSense watches inventory and competitor prices for Shopify and WooCommerce stores and sends alerts before products run out or get undercut. Customers are small Indian D2C stores in fashion, home and electronics accessories. MRR dipped last month after a few seasonal stores paused their plans.'),
 insights = '{"value_proposition":"Know before you run out or get undercut.","problem":"Small D2C stores lose sales to stock-outs and to competitors who quietly drop prices.","audience":"Shopify and WooCommerce stores in fashion, home and accessories","customer_type":"B2B","pricing":"Starter ₹999/month, Growth ₹2,499/month, quarterly plans","tech_stack":"Node.js, Postgres, Shopify API, WooCommerce API","acquisition_channels":"Shopify app store, D2C founder WhatsApp groups"}'::jsonb
 where id = '22222222-2222-4222-8222-000000000003';

-- A few insights for the new demo startups
update public.listings set founded_on = '2023-11-01', insights = '{"value_proposition":"Payroll and PF/ESI filings in one monthly run.","audience":"Indian companies with 10 to 200 staff","customer_type":"B2B","pricing":"Per company: ₹3,999, ₹6,999 and ₹11,999/month","tech_stack":"Django, Postgres, React, Razorpay"}'::jsonb where id = '22222222-2222-4222-8222-000000000004';
update public.listings set founded_on = '2024-06-01', insights = '{"value_proposition":"Plain-language contract summaries with clauses to double-check.","audience":"Small law firms, startups, HR teams","customer_type":"B2B","pricing":"₹2,499 and ₹7,999/month plus usage top-ups","tech_stack":"Next.js, Python, Claude API, Supabase"}'::jsonb where id = '22222222-2222-4222-8222-000000000007';
update public.listings set founded_on = '2024-02-01', insights = '{"value_proposition":"One dashboard for WhatsApp broadcasts and cart recovery.","audience":"D2C fashion and beauty brands","customer_type":"B2B","pricing":"₹2,999 and ₹5,999/month; one agency plan","tech_stack":"Node.js, WhatsApp Cloud API, Postgres","extra":"One reseller agency pays on a single account, which is why one customer is a large share of revenue."}'::jsonb where id = '22222222-2222-4222-8222-000000000009';

-- Founder updates (the "What's happening" feed)
delete from public.posts where listing_id::text like '22222222-2222-4222-8222-%';

-- If the marketplace-filters migration (20261022040000) has already run, mark the priced demo
-- startups as open to offers (ShipCompare has no price, so it stays "not for sale").
do $$
begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'listings' and column_name = 'is_for_sale') then
    execute $q$update public.listings set is_for_sale = (asking_price_inr is not null) where is_demo$q$;
    execute $q$update public.listings set business_model = case insights->>'customer_type' when 'B2B' then 'b2b' when 'B2C' then 'b2c' when 'B2B and B2C' then 'b2b2c' end where is_demo and business_model is null and insights ? 'customer_type'$q$;
  end if;
end $$;
