insert into public.traffic_daily (listing_id, date, active_users, sessions, is_demo) select '22222222-2222-4222-8222-000000000013', d::date, u, round(u * 1.35), true from (select d, greatest(20, round(1100 * (1 + 0.126 * ((extract(month from d) - 9))) * (case when extract(isodow from d) in (6,7) then 0.7 else 1 end) * (0.8 + ((extract(doy from d)::int * 37 + 13 * 11) % 41) / 100.0)))::int as u from generate_series('2026-04-01'::date, '2026-09-30'::date, interval '1 day') d) t;
insert into public.posts (listing_id, author_id, body, created_at) values
 ('22222222-2222-4222-8222-000000000001','11111111-1111-4111-8111-000000000001','Shipped automatic payment reminders on WhatsApp this week. Clients now get a gentle nudge 3 days after the due date, and a second one a week later. Early users say it saves them the awkward follow-up call.', now() - interval '3 hours'),
 ('22222222-2222-4222-8222-000000000007','11111111-1111-4111-8111-000000000007','DocuMitra now flags lock-in and auto-renewal clauses in rental agreements. Most requested feature from small law firms this month.', now() - interval '5 hours'),
 ('22222222-2222-4222-8222-000000000002','11111111-1111-4111-8111-000000000002','Hindi captions now handle Hinglish properly: mixed-script lines stay readable instead of being forced into Devanagari. Thanks to everyone who sent sample clips.', now() - interval '9 hours'),
 ('22222222-2222-4222-8222-000000000008','11111111-1111-4111-8111-000000000008','StackPulse cron monitoring is out of beta. You get a WhatsApp alert if a scheduled job doesn''t check in on time.', now() - interval '14 hours'),
 ('22222222-2222-4222-8222-000000000003','11111111-1111-4111-8111-000000000003','Added WooCommerce support for price-drop alerts. Shopify and WooCommerce stores can now track competitor prices from the same dashboard.', now() - interval '20 hours'),
 ('22222222-2222-4222-8222-000000000005','11111111-1111-4111-8111-000000000005','Fee reminders now go out in Hindi and Marathi. Coaching centres in Nagpur and Indore asked for it.', now() - interval '1 day'),
 ('22222222-2222-4222-8222-000000000001','11111111-1111-4111-8111-000000000001','Open to offers. Looking for someone who can take LedgerLoop to CA firms and agencies at scale. Happy to stay on for a 3-month handover.', now() - interval '2 days'),
 ('22222222-2222-4222-8222-000000000002','11111111-1111-4111-8111-000000000002','The September spike on our revenue chart is the lifetime-deal campaign. Kickoff flagged it automatically, which is fair: it is one-time money, not recurring.', now() - interval '4 days'),
 ('22222222-2222-4222-8222-000000000011','11111111-1111-4111-8111-000000000011','Moved yearly-plan refunds to pro-rata credits instead of cash refunds. Should bring the refund rate down from next month.', now() - interval '5 days');
